def split_legacy_photos(apps, schema_editor):
    Photo = apps.get_model("gallery", "Photo")
    GalleryChapter = apps.get_model("gallery", "GalleryChapter")
    PortfolioPhoto = apps.get_model("gallery", "PortfolioPhoto")
    SlideshowPhoto = apps.get_model("gallery", "SlideshowPhoto")
    database = schema_editor.connection.alias

    chapter_titles = ("Hääkuvat", "Perhekuvat", "Parikuvat", "Muut")
    chapters = {}
    for order, title in enumerate(chapter_titles):
        chapters[title] = GalleryChapter.objects.using(database).create(
            title=title,
            display_order=order,
        )

    for photo in Photo.objects.using(database).all().order_by("id"):
        if photo.slot_code in {"01", "02", "03", "04"}:
            SlideshowPhoto.objects.using(database).create(
                title=photo.title,
                slot_code=photo.slot_code,
                image=photo.image.name,
                is_published=photo.is_published,
            )
        if photo.show_in_gallery:
            PortfolioPhoto.objects.using(database).create(
                chapter=chapters["Muut"],
                title=photo.title,
                image=photo.image.name,
                description=photo.description,
                is_published=photo.is_published,
                display_order=photo.display_order,
            )


def restore_legacy_photos(apps, schema_editor):
    Photo = apps.get_model("gallery", "Photo")
    PortfolioPhoto = apps.get_model("gallery", "PortfolioPhoto")
    SlideshowPhoto = apps.get_model("gallery", "SlideshowPhoto")
    database = schema_editor.connection.alias

    for photo in SlideshowPhoto.objects.using(database).all():
        Photo.objects.using(database).create(
            title=photo.title,
            image=photo.image.name,
            description="",
            is_published=photo.is_published,
            display_order=0,
            slot_code=photo.slot_code,
            show_in_gallery=False,
        )
    for photo in PortfolioPhoto.objects.using(database).all():
        Photo.objects.using(database).create(
            title=photo.title,
            image=photo.image.name,
            description=photo.description,
            is_published=photo.is_published,
            display_order=photo.display_order,
            slot_code=None,
            show_in_gallery=True,
        )


